/**
 * 테스트케이스 목록 조회 완료
 */
scwin.sbm_selectTestCaseList_submitdone = function(e) {
    console.log("=== 실패한 테스트케이스 목록 조회 완료 ===");
    console.log("전체 응답:", e.responseJSON);

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`실패한 테스트케이스 조회 실패: ${elHeader ? elHeader.resMsg : "알 수 없는 오류"}`);
        return;
    }

    // 원본 unitTestList 데이터 확인
    var originalTestCaseList = elData.unitTestList || [];
    console.log("조회된 원본 테스트케이스 데이터:", originalTestCaseList);
    console.log("원본 테스트케이스 개수:", originalTestCaseList.length);

    // 클라이언트 사이드에서 FAIL 상태 필터링 (서버에서 필터링이 안 된 경우 대비)
    var failedTestCases = originalTestCaseList.filter(function(item) {
        var testStatus = item.testStatus || item.test_status || "";
        console.log("테스트케이스 상태 확인:", {
            testCaseId: item.testCaseId,
            testCaseName: item.testCaseName,
            testStatus: testStatus,
            isFail: testStatus === 'FAIL'
        });
        return testStatus === 'FAIL';
    });

    console.log("클라이언트 필터링 후 실패한 테스트케이스:", failedTestCases);
    console.log("실패한 테스트케이스 개수:", failedTestCases.length);

    if (failedTestCases.length === 0) {
        $c.win.alert("실행 결과가 '실패(FAIL)'인 테스트케이스가 없습니다.\n\n테스트를 먼저 실행하고 실패한 케이스에 대해 결함을 등록해주세요.");
        return;
    }

    // 실패한 테스트케이스만 매핑
    var properlyMappedList = failedTestCases.map(function(originalItem) {
        var mapped = {
            // testCaseId를 testId로 매핑
            testId: originalItem.testCaseId || originalItem.id || "",
            testCaseName: originalItem.testCaseName || "",
            assigneeName: originalItem.assigneeName || originalItem.assignee || "",

            // 추가 정보도 포함
            testTarget: originalItem.testTarget || "",
            testStatus: originalItem.testStatus || originalItem.test_status || "",
            priority: originalItem.priority || "",
            description: originalItem.description || ""
        };

        console.log("매핑 확인 (실패한 테스트케이스):", {
            원본testCaseId: originalItem.testCaseId,
            원본testStatus: originalItem.testStatus,
            변환된testId: mapped.testId,
            변환된testStatus: mapped.testStatus,
            테스트케이스명: mapped.testCaseName
        });

        return mapped;
    });

    console.log("최종 매핑된 실패 테스트케이스 데이터:", properlyMappedList);

    // 그리드에 데이터 설정
    dlt_testCaseList.setJSON(properlyMappedList);

    // 팝업 표시
    pop_testCaseSelect.show();

    // 팝업 제목 업데이트
    setTimeout(function() {
        try {
            spn_testCasePopupTitle.setValue("실패한 테스트케이스 선택 (" + properlyMappedList.length + "건)");
        } catch(e) {
            console.log("팝업 제목 설정 실패, 무시:", e);
        }
    }, 100);

    console.log("실패한 테스트케이스 선택 팝업 표시 완료");
};


scwin.sbm_selectTestCaseList_submiterror = function(e) {
    console.error("실패한 테스트케이스 목록 조회 실패:", e);
    $c.win.alert("실패한 테스트케이스 목록을 조회하는 중 오류가 발생했습니다.");
};


/**
 * 테스트케이스 목록 조회 완료
 */
scwin.sbm_selectTestCaseList_submitdone = function(e) {
    console.log("=== 테스트케이스 목록 조회 완료 ===");

    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (!elHeader || elHeader.resSuc == false) {
        $c.win.alert(`테스트케이스 조회 실패: ${elHeader ? elHeader.resMsg : "알 수 없는 오류"}`);
        return;
    }

    var testCaseList = elData.unitTestList || [];
    console.log("조회된 테스트케이스 원본 데이터:", testCaseList);

    if (testCaseList.length > 0) {
        console.log("첫 번째 데이터 구조:", testCaseList[0]);
        console.log("사용 가능한 키들:", Object.keys(testCaseList[0]));
    }

    // 안전한 데이터 변환 - null/undefined 체크 포함
    var convertedList = testCaseList.map(function(item, index) {
        // 각 필드를 안전하게 추출
        var converted = {
            id: item.testCaseId || item.id || "",
            testCaseName: item.testCaseName || item.test_case_name || item.name || "",
            description: item.description || "",
            status: item.testStatus || item.test_status || item.status || "",
            priority: item.priority || "",
            createdAt: item.createdAt || item.created_at || "",
            testTarget: item.testTarget || item.test_target || "",
            assigneeName: item.assigneeName || item.assignee_name || item.assignee || ""
        };

        console.log(`테스트케이스 ${index} 변환:`, {
            원본: {
                testCaseId: item.testCaseId,
                testCaseName: item.testCaseName,
                testTarget: item.testTarget,
                assigneeName: item.assigneeName
            },
            변환: {
                id: converted.id,
                testCaseName: converted.testCaseName,
                testTarget: converted.testTarget,
                assigneeName: converted.assigneeName
            }
        });

        return converted;
    });

    console.log("최종 변환된 데이터:", convertedList);

    // 빈 값이 있는지 체크
    var emptyFields = [];
    convertedList.forEach(function(item, index) {
        if (!item.testCaseName) emptyFields.push(`${index}번째 항목의 testCaseName이 비어있음`);
        if (!item.testTarget) emptyFields.push(`${index}번째 항목의 testTarget이 비어있음`);
    });

    if (emptyFields.length > 0) {
        console.warn("빈 필드 발견:", emptyFields);
    }

    // 그리드에 데이터 설정
    dlt_testCaseList.setJSON(convertedList);

    // 팝업 표시
    pop_testCaseSelect.show();

    console.log("테스트케이스 선택 팝업 표시 완료");
};

/**
 * 테스트케이스 선택
 */
scwin.selectTestCase = function(row, col, colId) {
    console.log("실패한 테스트케이스 선택 - 행:", row);

    var selectedTestCase = dlt_testCaseList.getRowJSON(row);
    console.log("선택된 실패한 테스트케이스:", selectedTestCase);

    // 변환된 데이터에서 실제 필드명 사용
    var testId = selectedTestCase.testId;  // 변환된 데이터에서는 'testId' 필드
    var testName = selectedTestCase.testCaseName;
    var testStatus = selectedTestCase.testStatus;

    console.log("설정할 데이터:", { 
        testId: testId, 
        testName: testName,
        testStatus: testStatus
    });

    if (!testId) {
        $c.win.alert("테스트케이스 ID가 없습니다. 다른 항목을 선택해주세요.");
        return;
    }

    if (!testName) {
        $c.win.alert("테스트케이스명이 없습니다. 다른 항목을 선택해주세요.");
        return;
    }

    // 실패 상태 확인 (추가 안전장치)
    if (testStatus && testStatus !== 'FAIL') {
        console.warn("선택된 테스트케이스가 FAIL 상태가 아닙니다:", testStatus);
    }

    // 결함 상세에 설정
    dmp_defDetail.set("testId", testId);
    dmp_defDetail.set("testName", testName + " (실패)");

    console.log("결함 상세에 설정 완료:", {
        testId: dmp_defDetail.get("testId"),
        testName: dmp_defDetail.get("testName")
    });

    // 팝업 닫기
    pop_testCaseSelect.hide();

    console.log("실패한 테스트케이스 선택 프로세스 완료");
};

