/**
 * 수정/삭제 권한 확인
 */
scwin.checkEditPermission = function(defData) {
    // PM이면 모든 결함 수정/삭제 가능
    if (scwin.isPM()) {
        return true;
    }

    // 일반 사용자는 자신이 담당한 결함만 수정/삭제 가능
    return defData.assignee === scwin.CURRENT_USER_ID;
};



