/**
 * 상세보기 팝업 표시
 */
scwin.showDetailPopup = function(mode) {
    console.log("상세보기 팝업 표시:", mode);

    var selectedData = dmp_defDetail.getJSON();

    // 수정 모드일 때 권한 확인
    if (mode === "edit" && !scwin.checkEditPermission(selectedData)) {
        $c.win.alert("본인이 담당한 결함만 수정할 수 있습니다.");
        return;
    }

    // 팝업 표시
    pop_overlay.show();

    // 모드 설정
    scwin.setFormMode(mode);

    // 제목 설정
    setTimeout(function() {
        try {
            var title = mode === "view" ? "결함 상세정보" : "결함 수정";
            spn_popupTitle.setValue(title);
        } catch(e) {
            setTimeout(function() {
                var title = mode === "view" ? "결함 상세정보" : "결함 수정";
                spn_popupTitle.setValue(title);
            }, 50);
        }
    }, 50);

    // 파일 목록 로드
    scwin.loadFileList();
};

/**
 * 신규 페이지 번호 클릭 이벤트
 */
scwin.pgl_new_onclick = function(idx) {
    console.log("신규 페이지 클릭:", idx);

    scwin.newPageInfo.currentPage = idx;
