/**
 * 폼 유효성 검사
 */
scwin.validateForm = function() {
    // 에디터 내용을 강제로 동기화
    try {
        if (editor_description && editor_description.blur) {
            editor_description.blur();
        }
        // 에디터에서 직접 HTML 내용 가져오기
        if (editor_description && typeof editor_description.getHTML === 'function') {
            var descriptionHTML = editor_description.getHTML();
            dmp_defDetail.set("description", descriptionHTML);
        }
    } catch(e) {
        console.log("에디터 내용 동기화 실패:", e);
    }

    var name = dmp_defDetail.get("name");
    var description = dmp_defDetail.get("description");

    if (!name || name.trim() === "") {
        $c.win.alert("결함명을 입력해주세요.");
        return false;
    }

    // HTML 태그를 제거한 순수 텍스트로 검사
    var plainText = "";
    if (description) {
        plainText = description.replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
    }

    if (!plainText || plainText === "") {
        $c.win.alert("결함 설명을 입력해주세요.");
        return false;
    }

    return true;
};

