/**
 * 파일과 함께 저장
 */
scwin.saveDefWithFiles = function() {
    console.log("=== 파일과 함께 저장 시작 ===");

    // 에디터 포커스 해제하여 내용 확정
    try {
        if (editor_description && editor_description.blur) {
            editor_description.blur();
        }
        if (editor_responsePlan && editor_responsePlan.blur) {
            editor_responsePlan.blur();
        }
    } catch(e) {
        console.log("에디터 blur 실패, 무시");
    }

    // 잠시 대기 후 저장 실행 (에디터 내용 동기화 시간 확보)
    setTimeout(function() {
        scwin.executeFileUploadWithData();
    }, 100);
};

/**
 * 실제 파일 업로드와 데이터 전송 실행
 */
scwin.executeFileUploadWithData = function() {
    console.log("=== 결함 등록 데이터 검증 시작 ===");

    // 에디터 내용을 먼저 확실하게 동기화
    try {
        var descriptionHTML = "";
        var responsePlanHTML = "";

        if (editor_description && typeof editor_description.getHTML === 'function') {
            descriptionHTML = editor_description.getHTML();
            console.log("결함설명 HTML:", descriptionHTML);
        }

        if (editor_responsePlan && typeof editor_responsePlan.getHTML === 'function') {
            responsePlanHTML = editor_responsePlan.getHTML();
            console.log("대응방안 HTML:", responsePlanHTML);
        }

        dmp_defDetail.set("description", descriptionHTML);
        dmp_defDetail.set("responsePlan", responsePlanHTML);

    } catch(e) {
        console.error("에디터 내용 가져오기 실패:", e);
    }

    // 전송할 데이터 검증
    var formData = new FormData();

    // 필수 데이터 검증 및 추가
    var testId = dmp_defDetail.get("testId") || "";
    var testName = dmp_defDetail.get("testName") || "";
    var name = dmp_defDetail.get("name") || "";
    var description = dmp_defDetail.get("description") || "";
    var priority = dmp_defDetail.get("priority") || "MD";
    var status = dmp_defDetail.get("status") || "NEW";
    var assignee = dmp_defDetail.get("assignee") || scwin.CURRENT_USER_ID;
    var fixDueDate = dmp_defDetail.get("fixDueDate") || "";
    var fixedDate = dmp_defDetail.get("fixedDate") || "";
    var responsePlan = dmp_defDetail.get("responsePlan") || "";
    var pjtId = dmp_defDetail.get("pjtId") || scwin.CURRENT_PROJECT_ID;

    console.log("=== 전송 데이터 검증 ===");
    console.log("testId:", testId, "(타입:", typeof testId, ")");
    console.log("testName:", testName, "(타입:", typeof testName, ")");
    console.log("name:", name, "(타입:", typeof name, ")");
    console.log("description 길이:", description.length);
    console.log("priority:", priority, "(타입:", typeof priority, ")");
    console.log("status:", status, "(타입:", typeof status, ")");
    console.log("assignee:", assignee, "(타입:", typeof assignee, ")");
    console.log("pjtId:", pjtId, "(타입:", typeof pjtId, ")");

    // 필수 필드 검증
    if (!name || name.trim() === "") {
        $c.win.alert("결함명은 필수입니다.");
        return;
    }

    if (!assignee || assignee.trim() === "") {
        $c.win.alert("담당자는 필수입니다.");
        return;
    }

    // HTML 태그 제거 후 description 검증
    var plainDescription = description.replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
    if (!plainDescription || plainDescription === "") {
        $c.win.alert("결함 설명은 필수입니다.");
        return;
    }

    // FormData에 데이터 추가 (문자열로 변환하여 추가)
    formData.append("testId", String(testId));
    formData.append("testName", String(testName));
    formData.append("name", String(name));
    formData.append("description", String(description));
    formData.append("priority", String(priority));
    formData.append("status", String(status));
    formData.append("assignee", String(assignee));
    formData.append("fixDueDate", String(fixDueDate));
    formData.append("fixedDate", String(fixedDate));
    formData.append("responsePlan", String(responsePlan));
    formData.append("pjtId", String(pjtId));

    // 파일 추가
    var hasValidFiles = false;
    if (mpd_html5Type && mpd_html5Type.fileArray) {
        var fileList = mpd_html5Type.fileArray;
        console.log("파일 배열:", fileList);
        console.log("파일 배열 길이:", fileList ? fileList.length : 0);

        if (fileList && fileList.length > 0) {
            for (var i = 0; i < fileList.length; i++) {
                var fileItem = fileList[i];
                var realFile = fileItem.file || fileItem;

                if (realFile && realFile instanceof File && realFile.size > 0) {
                    formData.append("files", realFile);
                    hasValidFiles = true;
                    console.log("파일 추가 성공:", realFile.name, "크기:", realFile.size);
                } else {
                    console.warn("유효하지 않은 파일:", realFile);
                }
            }
        }
    }

    console.log("유효한 파일 존재 여부:", hasValidFiles);

    // FormData 내용 확인 (디버깅용)
    console.log("=== FormData 내용 확인 ===");
    for (var pair of formData.entries()) {
        if (pair[1] instanceof File) {
            console.log(pair[0] + ': ' + pair[1].name + ' (' + pair[1].size + ' bytes)');
        } else {
            console.log(pair[0] + ': ' + pair[1]);
        }
    }

    // 서버로 전송
    console.log("=== 서버 전송 시작 ===");
    fetch("/InsWebApp/DEF001InsWithFiles.pwkjson", {
        method: "POST",
        body: formData
    })
    .then(function(res) { 
        console.log("HTTP 응답 상태:", res.status, res.statusText);

        if (!res.ok) {
            throw new Error('HTTP ' + res.status + ': ' + res.statusText);
        }
        return res.json(); 
    })
    .then(function(res) {
        console.log("=== 서버 응답 받음 ===");
        console.log("전체 응답:", res);

        var elHeader = res.elHeader;
        console.log("elHeader:", elHeader);

        if (elHeader && elHeader.resSuc === true) {
            $c.win.alert("등록되었습니다.");

            // 파일 목록 초기화
            dlt_upload.setJSON([]);
            if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
                mpd_html5Type.removeAllFiles();
            }

            pop_overlay.hide();

            // 목록 새로고침
            if (scwin.CURRENT_PROJECT_ID && scwin.CURRENT_PROJECT_ID !== "") {
                scwin.searchDefectsByProject();
            } else {
                scwin.searchDefects();
            }
        } else {
            var errorMsg = "등록에 실패했습니다.";
            if (elHeader && elHeader.resMsg) {
                errorMsg += "\n서버 오류: " + elHeader.resMsg;
            }
            if (elHeader && elHeader.resCode) {
                errorMsg += "\n오류코드: " + elHeader.resCode;
            }
            console.error("서버에서 실패 응답:", elHeader);
            $c.win.alert(errorMsg);
        }
    })
    .catch(function(err) {
        console.error("=== 전송 실패 ===");
        console.error("오류 객체:", err);
        console.error("오류 메시지:", err.message);
        console.error("스택 트레이스:", err.stack);

        var errorMsg = "등록 중 오류가 발생했습니다.";
        if (err.message) {
            errorMsg += "\n상세 오류: " + err.message;
        }
        $c.win.alert(errorMsg);
    });
};

